code_sketch:
struct Money: Equatable {
    let minor: Int
    let currency: Currency

    static func + (lhs: Money, rhs: Money) -> Money {
        precondition(lhs.currency == rhs.currency, "currency mismatch")
        return Money(minor: lhs.minor + rhs.minor, currency: lhs.currency)
    }
}

extension Money: AdditiveArithmetic {
    static let zero = Money(minor: 0, currency: .none)   // only if the domain has one
}
